import torch

CORR_LENGTHS = {
    (5,): [2, 0, 3],
    (2, 3): [[1, 1, 1], [1, 1, 1]],
    (2, 3, 4): [[1, 2], [2, 1]],
    (2, 3, 5): [[[2, 3], [1, 4], [3, 2]], [[5, 0], [2, 3], [4, 1]]],
}


def _make_data(shape, dtype, device):
    numel = 1
    for s in shape:
        numel *= s
    values = torch.arange(1, 1 + numel, device=device).reshape(shape).to(torch.float32)
    values = (values.remainder(17) - 8) / 5
    values = values + 0.25
    return values.to(dtype)


def _make_lengths(shape, axis, device):
    size_axis = shape[axis]
    segment_count = min(64, size_axis)
    base_length = size_axis // segment_count
    remainder = size_axis % segment_count
    lengths = torch.full((segment_count,), base_length, dtype=torch.int64)
    if remainder:
        lengths[:remainder] += 1
    outer_shape = tuple(shape[:axis])
    if outer_shape:
        lengths = lengths.expand(*outer_shape, segment_count).clone()
    return lengths.to(device)


def run(data, reduce, lengths, axis, unsafe, initial):
    return torch.segment_reduce(
        data, reduce, lengths=lengths, axis=axis, unsafe=unsafe, initial=initial
    )


def gen_inputs(ctx, device):
    shape = tuple(ctx['data__shape'])
    dtype = getattr(torch, ctx['data__dtype'])
    axis = ctx['axis']
    if shape in CORR_LENGTHS:
        data = _make_data(shape, dtype, device)
        lengths = torch.tensor(CORR_LENGTHS[shape], dtype=torch.int64, device=device)
    else:
        data = torch.randn(shape, dtype=dtype, device=device)
        lengths = _make_lengths(shape, axis, device)
    return {'data': data, 'lengths': lengths}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    ref = ref_outputs[0].detach().to('cpu').to(torch.float64)
    sol = sol_outputs[0].detach().to('cpu').to(torch.float64)
    if ref.shape != sol.shape:
        return {'passed': False, 'message': 'shape mismatch', 'metrics': {}}
    rtol = 1.3e-6
    atol = 1e-4
    both_nan = torch.isnan(ref) & torch.isnan(sol)
    both_posinf = torch.isposinf(ref) & torch.isposinf(sol)
    both_neginf = torch.isneginf(ref) & torch.isneginf(sol)
    finite = torch.isfinite(ref) & torch.isfinite(sol)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = (ref[finite] - sol[finite]).abs() <= atol + rtol * ref[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {'passed': bool(ok), 'message': '', 'metrics': {}}
